<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3';
import { nextTick, ref, watch } from 'vue';
import AccountLayout from '../../../layouts/AccountLayout.vue';
import CommercialErrors from '../../../components/CommercialErrors.vue';
import { money } from '../../../types/catalog';
import { availabilityLabel, localDate, toMinor, type CommercialProduct, type Supplier, type SupplierOffer, type PricingQuote } from '../../../types/commercial';
const props=defineProps<{ product:CommercialProduct;offers:SupplierOffer[];suppliers:Supplier[];quote:PricingQuote;override:string;canManage:boolean }>();
const selected=ref<number|null>(null),cost=ref(''),observed=ref(localDate());
const form=useForm({supplier_id:'' as number|string,supplier_sku:'',reference:'',cost_minor:null as number|null,currency:props.product.currency,stock:null as number|null,availability:'unknown',observed_at:'',active:true,notes:''});
const settings=useForm({preferred_offer_id:props.quote.preferred_offer_id,multiplier:props.override});
const apply=useForm({revision:props.quote.revision});
watch(()=>props.quote.revision,revision=>{apply.revision=revision;});
const focus=(prefix:string)=>nextTick(()=>document.getElementById(prefix)?.focus());
function edit(offer:SupplierOffer){selected.value=offer.id;form.supplier_id=offer.supplier_id;form.supplier_sku=offer.supplier_sku;form.reference=offer.reference??'';form.currency=offer.currency;form.stock=offer.stock;form.availability=offer.availability;form.active=offer.active;form.notes=offer.notes??'';cost.value=offer.cost_minor===null?'':(offer.cost_minor/100).toFixed(2);observed.value=localDate(offer.observed_at);focus('offer-form');}
function reset(){selected.value=null;form.reset();cost.value='';observed.value=localDate();focus('offer-form');}
function save(){form.cost_minor=toMinor(cost.value);form.observed_at=observed.value?new Date(observed.value).toISOString():'';const options={preserveScroll:true,onError:()=>focus('offer-errors')};if(selected.value)form.put(`/admin/commercial/products/${props.product.id}/offers/${selected.value}`,options);else form.post(`/admin/commercial/products/${props.product.id}/offers`,{...options,onSuccess:reset});}
</script>
<template><Head :title="`Ofertas · ${product.name}`"><meta name="robots" content="noindex, nofollow"/></Head><AccountLayout :title="product.name" section="admin"><Link :href="`/admin/catalog/products/${product.id}/edit`">← Detalle del producto</Link><p v-if="product.is_demo" class="notice">DEMO · Este registro no representa información comercial real.</p><p v-if="!canManage" class="notice">Consulta de operator. Los costos son privados; no se muestran en la tienda.</p><div class="commercial-cards"><section class="info-card is-consult"><p class="eyebrow">PRECIO PÚBLICO VIGENTE</p><h2>{{ money(product.price_minor,product.currency) }}</h2><p>{{ product.currency }} · Autoridad para carrito y checkout</p></section><section class="info-card is-consult"><p class="eyebrow">SUGERENCIA INTERNA</p><h2>{{ quote.suggested_minor===null?'Por completar':money(quote.suggested_minor,quote.currency) }}</h2><p>{{ quote.rule ?? 'Sin regla' }}</p><p v-if="quote.cost_minor!==null && quote.cost_currency">{{ money(quote.cost_minor,quote.cost_currency) }} × {{ quote.multiplier ?? '—' }}</p><p v-if="quote.reason" role="status">{{ quote.reason }}</p><p v-if="quote.preferred_offer_id" class="muted">Disponibilidad conocida: {{ availabilityLabel(quote.availability??'unknown') }} · Stock: {{ quote.stock ?? 'Desconocido' }}. No es una reserva.</p><CommercialErrors :errors="apply.errors" prefix="apply-errors"/><button v-if="canManage" class="button" :disabled="quote.suggested_minor===null || apply.processing" @click="apply.post(`/admin/commercial/products/${product.id}/apply-price`,{preserveScroll:true,onError:()=>focus('apply-errors')})">Aplicar precio sugerido</button><p class="muted">Acción explícita. No modifica pedidos anteriores.</p></section></div><form class="info-card is-work compact-form" @submit.prevent="settings.put(`/admin/commercial/products/${product.id}/settings`,{preserveScroll:true,onError:()=>focus('settings-errors')})"><h2>Oferta preferida y excepción</h2><fieldset :disabled="!canManage || settings.processing"><label>Oferta preferida<select v-model="settings.preferred_offer_id"><option :value="null">Sin oferta preferida</option><option v-for="offer in offers" :key="offer.id" :value="offer.id" :disabled="!offer.active || !offer.supplier?.active">{{ offer.supplier?.name }} · {{ offer.supplier_sku }} {{ !offer.active ? '(inactiva)' : '' }}</option></select></label><label>Multiplicador del producto (opcional)<input v-model="settings.multiplier" inputmode="decimal" maxlength="8" placeholder="Vacío: usar regla de categoría" :aria-invalid="!!settings.errors.multiplier" aria-describedby="settings-errors-multiplier"></label><CommercialErrors :errors="settings.errors" prefix="settings-errors"/><button v-if="canManage" class="button">Guardar preferencia</button></fieldset><Link href="/admin/commercial/rules" class="quiet-link rules-link">Administrar reglas por categoría →</Link></form><h2>Ofertas de proveedores</h2><p class="muted">Información manual. No seleccionamos automáticamente el menor costo.</p><p v-if="!offers.length" class="notice">Todavía no hay ofertas. Ingresa únicamente SKU, costo y disponibilidad confirmados.</p><div class="commercial-cards"><article v-for="offer in offers" :key="offer.id" class="info-card is-consult"><h3>{{ offer.supplier?.name }}</h3><p v-if="offer.id===quote.preferred_offer_id" class="notice">Preferida</p><p>SKU: <span class="code">{{ offer.supplier_sku }}</span></p><p>Costo: {{ offer.cost_minor===null?'No confirmado':money(offer.cost_minor,offer.currency) }}</p><p>{{ offer.currency }} · {{ availabilityLabel(offer.availability) }} · Stock: {{ offer.stock??'Desconocido' }}</p><p>{{ offer.active?'Activa':'Inactiva' }} · Fuente: {{ offer.source }}</p><p>Observado: {{ new Date(offer.observed_at).toLocaleString('es-CR') }}</p><button v-if="canManage" class="quiet-link" @click="edit(offer)">Editar oferta de {{ offer.supplier?.name }}</button></article></div><form v-if="canManage" id="offer-form" tabindex="-1" class="info-card is-work compact-form" @submit.prevent="save"><h2>{{ selected ? 'Editar oferta' : 'Nueva oferta' }}</h2><fieldset :disabled="form.processing"><div class="form-grid"><label>Proveedor<select v-model="form.supplier_id" required><option value="" disabled>Seleccionar</option><option v-for="supplier in suppliers" :key="supplier.id" :value="supplier.id">{{ supplier.name }} {{ !supplier.active?'(inactivo)':'' }}</option></select></label><label>SKU del proveedor<input v-model="form.supplier_sku" class="code" required maxlength="100" :aria-invalid="!!form.errors.supplier_sku" aria-describedby="offer-errors-supplier_sku"></label><label>Modelo / referencia (opcional)<input v-model="form.reference" maxlength="180"></label><label>Costo confirmado (opcional)<input v-model="cost" inputmode="decimal" :aria-invalid="!!form.errors.cost_minor" aria-describedby="offer-errors-cost_minor"><small>Vacío significa desconocido, nunca cero.</small></label><label>Moneda del costo<select v-model="form.currency"><option value="CRC">CRC</option><option value="USD">USD</option></select></label><label>Disponibilidad conocida<select v-model="form.availability"><option value="unknown">Desconocida</option><option value="available">Disponible</option><option value="unavailable">Sin disponibilidad</option></select></label><label>Stock conocido (opcional)<input v-model="form.stock" type="number" min="0" step="1" :aria-invalid="!!form.errors.stock" aria-describedby="offer-errors-stock"></label><label>Fecha y hora observada<input v-model="observed" type="datetime-local" required :aria-invalid="!!form.errors.observed_at" aria-describedby="offer-errors-observed_at"></label></div><label>Notas privadas<textarea v-model="form.notes" maxlength="2000"/></label><label class="inline-choice"><input v-model="form.active" type="checkbox"> Oferta activa</label><CommercialErrors :errors="form.errors" prefix="offer-errors"/><button class="button">Guardar oferta</button><button v-if="selected" type="button" class="quiet-link" @click="reset">Cancelar edición</button></fieldset></form></AccountLayout></template>
